 } public function current_screen() { $screen = get_current_screen(); if ($screen->base != 'upload') add_action( 'restrict_manage_posts', array($this, 'restrict_manage_posts'), 10, 2 ); } public function restrict_manage_posts($post_type, $which) { $post_type_object = get_post_type_object($post_type); if ($post_type_object->public && $post_type_object->show_ui) { $args = array( 'posts_per_page' => -1, 'post_type' => 'qqworld-collections' ); $projects = get_posts($args); if (count($projects)) { $_collection_project = isset($_GET['_collection_project']) ? $_GET['_collection_project'] : ''; print '<select name="_collection_project" id="filter-by-collection-project">'; print '<option value="">'.__('All Collection Projects', $this->text_domain).'</option>'; foreach ($projects as $project) { $selected = $project->ID == $_collection_project ? ' selected' : ''; print '<option value="'.$project->ID.'"'.$selected.'>'.$project->post_title.'</option>'; } print '</select>'; } } } public function parse_query( $query ) { global $pagenow; if (is_admin() && $pagenow=='edit.php' && isset($_GET['_collection_project']) && $_GET['_collection_project']) { $post_type = isset($_GET['post_type']) ? $_GET['post_type'] : 'post'; if ($query->query_vars['post_type'] == $post_type) { $query->query_vars['meta_key'] = '_collection_project'; $query->query_vars['meta_value'] = $_GET['_collection_project']; } } return $query; } public function admin_notices() { global $wpdb; if ( apply_filters( 'qqworld-collector-activated-license', false ) ) { switch ($this->options->qc_collection_project_core) { case 'querylist': if (!file_exists(WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR . 'querylist' . DIRECTORY_SEPARATOR . 'autoload.php')) { $class = 'notice notice-error'; $message = sprintf(__('The <strong>Software Development Kit (SDK)</strong> dedicated for collection project is missing. Please click <a href="%s" target="_blank">here</a> to install <strong>%s</strong>.', $this->text_do